#include <linux/module.h>
#include <linux/kernel.h>

static int __init mon_init(void) {
  printk(KERN_INFO "Driver charge\n");
  return 0;
}
static void __exit mon_exit(void) {
  printk(KERN_INFO "Driver decharge\n");
}
module_init(mon_init);
module_exit(mon_exit);
MODULE_LICENSE("GPL");

#include <linux/fs.h>
#include <linux/cdev.h>
static struct cdev mon_cdev;
static dev_t mon_devnum;

static int mon_open(struct inode *inode, struct file *file) {
  return 0;
}
static struct file_operations mon_fops = {
  .owner = THIS_MODULE,
  .open = mon_open,
};

/dts-v1/;
/ {
  compatible = "exemple,carte";
  soc {
    uart0: serial@10000000 {
      compatible = "ns16550a";
      reg = <0x10000000 0x1000>;
    };
  };
};

leds {
  compatible = "gpio-leds";
  led-aliment {
    label = "aliment";
    gpios = <&gpio4 0 GPIO_ACTIVE_HIGH>;
  };
};
